import{_ as a,o as d,c as r,a2 as l}from"./chunks/framework.CqpfiAoK.js";const u=JSON.parse('{"title":"قانون ضمان التعليم","description":"","frontmatter":{},"headers":[],"relativePath":"ar/0043-教育保障法.md","filePath":"ar/0043-教育保障法.md"}'),e={name:"ar/0043-教育保障法.md"};function i(o,t,h,n,s,b){return d(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="قانون-ضمان-التعليم" tabindex="-1">قانون ضمان التعليم <a class="header-anchor" href="#قانون-ضمان-التعليم" aria-label="Permalink to &quot;قانون ضمان التعليم&quot;">​</a></h1><table tabindex="0"><thead><tr><th>العنصر</th><th>المحتوى</th></tr></thead><tbody><tr><td>رقم الوثيقة</td><td>43</td></tr><tr><td>الوحدة</td><td>النظام القانوني وإطار الحوكمة</td></tr><tr><td>الكلمات المفتاحية</td><td>الحق في التعليم، التعليم التكافلي، نقل الزراعة، التعلم مدى الحياة، العدالة التعليمية</td></tr></tbody></table><h2 id="أولاً-الغرض-التشريعي-والمبادئ-الأساسية" tabindex="-1">أولاً: الغرض التشريعي والمبادئ الأساسية <a class="header-anchor" href="#أولاً-الغرض-التشريعي-والمبادئ-الأساسية" aria-label="Permalink to &quot;أولاً: الغرض التشريعي والمبادئ الأساسية&quot;">​</a></h2><p><em>قانون ضمان التعليم</em> أحد القوانين الخمسة المساندة لحضارة التكافل المرساة. يهدف إلى ضمان حق التعليم لجميع الكائنات داخل كون هنغ يوان، وإنشاء نظام تعليمي يتخذ «التطور التكافلي» مفهوماً جوهرياً، وتوفير الدعم المعرفي والكفاءات لتقدم عشرة آلاف عرق معاً.</p><p>يحدد هذا القانون المبادئ الأساسية التالية:</p><table tabindex="0"><thead><tr><th>المبدأ</th><th>المضمون</th></tr></thead><tbody><tr><td>العدالة التعليمية</td><td>جميع الكائنات، بغض النظر عن العرق أو الزراعة أو الأصل، تحصل على فرص تعليمية متساوية</td></tr><tr><td>التعليم حسب القدرات</td><td>احترام اختلافات المواهب واختيارات مسار التطور لكل كائن، وتقديم خطط تعليمية شخصية</td></tr><tr><td>وحدة المعرفة والعمل</td><td>الجمع بين المعرفة النظرية والزراعة العملية؛ ومعارضة التعليم الكلامي المنفصل عن الواقع</td></tr><tr><td>الانفتاح والمشاركة</td><td>الموارد التعليمية مفتوحة للمجتمع كله؛ والأساليب الأساسية لثلاثمائة نظام زراعة أصلي تدرس مجاناً</td></tr><tr><td>التعلم مدى الحياة</td><td>التعليم يخترق عملية الحياة كلها، ويدعم التعلم المستمر ورفع القدرات في جميع المراحل</td></tr><tr><td>التعددية الثقافية</td><td>احترام التقاليد الثقافية لجميع الأعراق، وتشجيع التبادل الثقافي التعددي والتعلم المتبادل</td></tr></tbody></table><h2 id="ثانياً-الضمانات-القانونية-للحق-في-التعليم" tabindex="-1">ثانياً: الضمانات القانونية للحق في التعليم <a class="header-anchor" href="#ثانياً-الضمانات-القانونية-للحق-في-التعليم" aria-label="Permalink to &quot;ثانياً: الضمانات القانونية للحق في التعليم&quot;">​</a></h2><p>ينص هذا القانون صراحةً على أن الحق في التعليم حق أساسي يمنحه الدستور التكافلي لكل كائن، وعلى الدولة والحضارة واجب ضمان تحقيق هذا الحق:</p><ol><li><strong>التعليم الأساسي المجاني</strong>: لجميع الكائنات الحق في تلقي تعليم أساسي مجاني، بما في ذلك المعارف العامة والأساليب الزراعية الأساسية ومفاهيم الحضارة التكافلية وغيرها، ومدة الدراسة من ست إلى اثنتي عشرة سنة، تُعدل وفق دورة نمو كل عرق.</li><li><strong>الدخول المجاني إلى الزراعة</strong>: الأساليب الأساسية لثلاثمائة نظام زراعة أصلي مفتوحة لجميع الكائنات مجاناً؛ ولا يجوز لأي منظمة أو فرد تملك الأساليب الزراعية الأساسية وتعليمها مقابل أجر.</li><li><strong>تكافؤ فرص الارتقاء</strong>: لا يجوز للمؤسسات التعليمية على اختلاف مستوياتها وضع شروط تمييزية على أساس العرق أو الزراعة أو الأصل في القبول؛ ومعايير القبول علنية وشفافة.</li><li><strong>ضمانات التعليم الخاص</strong>: توفير موارد تعليمية خاصة ملائمة ودعم تعليم عن بعد لفئات كالأحياء ذوي الإعاقة والأحياء من الأعراق الأخرى والأحياء في الأبعاد النائية.</li><li><strong>نظام الإعانة التعليمية</strong>: توفير منح دراسية وجوائز تفوق وقروض بلا فوائد للمتعلمين ذوي الصعوبات الاقتصادية، لضمان عدم فقدان فرص التعليم لأسباب مالية.</li></ol><h2 id="ثالثاً-بنية-النظام-التعليمي" tabindex="-1">ثالثاً: بنية النظام التعليمي <a class="header-anchor" href="#ثالثاً-بنية-النظام-التعليمي" aria-label="Permalink to &quot;ثالثاً: بنية النظام التعليمي&quot;">​</a></h2><p>ينقسم النظام التعليمي في حضارة التكافل المرساة إلى أربعة مستويات مترابطة عضوياً:</p><table tabindex="0"><thead><tr><th>المستوى</th><th>الاسم</th><th>الهدف</th><th>مدة الدراسة</th></tr></thead><tbody><tr><td>المستوى الأول</td><td>التعليم التمهيدي</td><td>تنمية القدرات المعرفية الأساسية والوعي التكافلي؛ وتعليم الأساليب الزراعية الأساسية</td><td>3-6 سنوات</td></tr><tr><td>المستوى الثاني</td><td>التعليم الأساسي</td><td>تعلم منهجي للمعارف العامة ونظريات الزراعة؛ واكتشاف اتجاهات مواهب الفرد</td><td>6-9 سنوات</td></tr><tr><td>المستوى الثالث</td><td>التعليم المهني</td><td>تعلم وممارسة معمقان في نظام الزراعة المختار أو المجال المهني</td><td>3-10 سنوات</td></tr><tr><td>المستوى الرابع</td><td>البحث المتقدم</td><td>استكشاف حدودي وبحث ابتكاري للمزارعين المتقدمين والباحثين</td><td>غير محدود</td></tr></tbody></table><p>بالإضافة إلى ذلك، يُنشأ «نظام شبكة الموجهين»: المزارعون الذين يبلغون درجة زراعية معينة عليهم واجب إرشاد المزارعين المبتدئين في حدود قدراتهم؛ وتحسب مساهمات الإرشاد ضمن كمية المساهمة في آلية التعاقد المشترك على الإنتاج، وتنال التوزيع المقابل للموارد.</p><h2 id="رابعاً-المؤسسات-التعليمية-والمعلمون" tabindex="-1">رابعاً: المؤسسات التعليمية والمعلمون <a class="header-anchor" href="#رابعاً-المؤسسات-التعليمية-والمعلمون" aria-label="Permalink to &quot;رابعاً: المؤسسات التعليمية والمعلمون&quot;">​</a></h2><ul><li><strong>المؤسسات التعليمية العامة</strong>: تنشئها الدولة أو جماعة الحضارة، وتتولى التعليم الأساسي المجاني والخدمات التعليمية العامة، بتمويل مضمون من التراكم العام.</li><li><strong>المؤسسات التعليمية الخاصة</strong>: تنشئها القوى الاجتماعية وفقاً للقانون؛ ويمكنها تقاضي رسوم معقولة، لكن يجب أن تخضع لإشراف السلطات التعليمية المختصة، ولا يجوز لها القيام بإعلانات كاذبة أو رسوم افتراسية.</li><li><strong>طوائف الزراعة</strong>: يمكن للمنظمات الزراعية التقليدية، بعد التسجيل، العمل كمؤسسات تعليمية مهنية؛ ويجب عليها الالتزام بقانون التعليم وعدم احتكار موارد الزراعة بشكل مغلق.</li><li><strong>حقوق وواجبات المعلمين</strong>: يتمتع المعلمون بحقوق الحرية الأكاديمية والأجر المعقول والتدريب المهني، ويحملون في الوقت نفسه واجبات التعليم والتربية والقدوة الحسنة وحماية خصوصية الطلاب.</li></ul><h2 id="خامساً-المحتوى-التعليمي-ومعايير-المناهج" tabindex="-1">خامساً: المحتوى التعليمي ومعايير المناهج <a class="header-anchor" href="#خامساً-المحتوى-التعليمي-ومعايير-المناهج" aria-label="Permalink to &quot;خامساً: المحتوى التعليمي ومعايير المناهج&quot;">​</a></h2><p>يجب أن يستوفي المحتوى التعليمي المتطلبات التالية:</p><ol><li>تضمين المفاهيم الجوهرية للحضارة التكافلية والتعليم المناهض للافتراس، لتنمية الوعي التكافلي لدى المتعلمين.</li><li>تضمين النظريات الأساسية والأساليب التمهيدية لثلاثمائة نظام زراعة أصلي.</li><li>تضمين المعارف العلمية العامة كقوانين الكون ومعارف الأبعاد وعلوم الحياة.</li><li>تضمين تاريخ وثقافة عشرة آلاف عرق، لتعزيز التفاهم والاحترام المتبادل بين الأعراق.</li><li>تضمين عناصر الزراعة العملية والخدمة الاجتماعية، لتنمية القدرة على وحدة المعرفة والعمل.</li><li>حظر نشر مفاهيم الزراعة الافتراسية والأفكار التمييزية.</li></ol><h2 id="سادساً-المسؤولية-القانونية" tabindex="-1">سادساً: المسؤولية القانونية <a class="header-anchor" href="#سادساً-المسؤولية-القانونية" aria-label="Permalink to &quot;سادساً: المسؤولية القانونية&quot;">​</a></h2><p>تتحمل الأفعال المخالفة لأحكام هذا القانون المسؤوليات التالية حسب جسامة الظروف:</p><ul><li>رفض أو إعاقة الأحياء في سن الدراسة من تلقي التعليم الإلزامي: الأمر بالتصحيح والعقاب.</li><li>المؤسسات التعليمية التي تتقاضى رسوماً مخالفة أو تعلن إعلانات كاذبة: الأمر بإرجاع الرسوم ودفع غرامة، وفي الحالات الجسيمة إلغاء ترخيص إدارة المدارس.</li><li>المعلمون الذين يعاقبون الطلاب بدنياً أو يميزون ضدهم: توقيع جزاءات، وفي الحالات الجسيمة إلغاء صفة المعلم وتطبيق المسؤولية القانونية.</li><li>من يملكون الموارد الزراعية العامة أو يحتكرون الرسوم: مصادرة العائدات غير المشروعة ودفع غرامة.</li></ul><h2 id="الخاتمة" tabindex="-1">الخاتمة <a class="header-anchor" href="#الخاتمة" aria-label="Permalink to &quot;الخاتمة&quot;">​</a></h2><p><em>قانون ضمان التعليم</em> هو الممارسة التعليمية لفلسفة «لكل فرد طريق» في حضارة التكافل المرساة. بضمان الحق في التعليم، وبناء نظام تعليمي متعدد المستويات، وفتح موارد الزراعة، يضمن حصول كل كائن على مسار تطور يناسبه، ويغذي تقدم عشرة آلاف عرق معاً بالمعرفة والكفاءات باستمرار.</p><h2 id="الوثائق-ذات-الصلة" tabindex="-1">الوثائق ذات الصلة <a class="header-anchor" href="#الوثائق-ذات-الصلة" aria-label="Permalink to &quot;الوثائق ذات الصلة&quot;">​</a></h2><ul><li>40-共生宪法总纲 (الدستور التكافلي: المبادئ العامة)</li><li>37-共生教育体系 (نظام التعليم التكافلي)</li><li>10-三百套本源修炼体系总览 (نظرة عامة على ثلاثمائة نظام زراعة أصلي)</li><li>08-人人有路保障体系 (نظام ضمان طريق لكل فرد)</li></ul>',25)])])}const _=a(e,[["render",i]]);export{u as __pageData,_ as default};
